package ec.edu.ucacue.odontocare.treatment.application;
import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import ec.edu.ucacue.odontocare.auth.application.UserPrincipal;import ec.edu.ucacue.odontocare.clinicalrecord.application.*;import ec.edu.ucacue.odontocare.clinicalrecord.domain.DentalEvolution;import ec.edu.ucacue.odontocare.clinicalrecord.infrastructure.*;import ec.edu.ucacue.odontocare.odontogram.domain.DentalPiece;import ec.edu.ucacue.odontocare.odontogram.infrastructure.DentalPieceRepository;import ec.edu.ucacue.odontocare.treatment.domain.*;import ec.edu.ucacue.odontocare.treatment.infrastructure.*;import ec.edu.ucacue.odontocare.treatment.presentation.*;
@Service public class TreatmentService{
 private final ClinicalRecordRepository records;private final DentalConsultationRepository consultations;private final DiagnosisRepository diagnoses;private final DentalPieceRepository pieces;private final ProcedureTypeRepository types;private final DentalProcedureRepository procedures;private final TreatmentPlanRepository plans;private final TreatmentPlanItemRepository items;private final DentalEvolutionRepository evolutions;
 public TreatmentService(ClinicalRecordRepository r,DentalConsultationRepository c,DiagnosisRepository d,DentalPieceRepository p,ProcedureTypeRepository t,DentalProcedureRepository pr,TreatmentPlanRepository plans,TreatmentPlanItemRepository items,DentalEvolutionRepository e){records=r;consultations=c;diagnoses=d;pieces=p;types=t;procedures=pr;this.plans=plans;this.items=items;evolutions=e;}
 @Transactional public ProcedureResponse createProcedure(Long recordId,Long consultationId,ProcedureRequest request,UserPrincipal user){requireRecord(recordId);var consultation=consultations.findByIdAndClinicalRecordId(consultationId,recordId).orElseThrow(()->new ConsultationNotFoundException(consultationId));if(request.diagnosisId()!=null&&!diagnoses.existsByIdAndConsultationId(request.diagnosisId(),consultationId))throw new TreatmentException("DIAGNOSIS_MISMATCH","El diagnóstico no pertenece a la consulta.");var type=types.findByCodeAndActiveTrue(request.type().name()).orElseThrow(()->new TreatmentException("PROCEDURE_TYPE_INVALID","Tipo de procedimiento no disponible."));Set<DentalPiece> related=resolvePieces(request.pieceCodes());var saved=procedures.save(new DentalProcedure(consultation,type,request.diagnosisId(),request.description(),request.materialUsed(),request.anesthesiaUsed(),request.postInstructions(),request.status(),request.date(),request.nextControl(),user.id(),related));return procedure(saved);}
 @Transactional(readOnly=true)public List<ProcedureResponse> procedures(Long recordId){requireRecord(recordId);return procedures.findByConsultationClinicalRecordIdOrderByPerformedAtDescIdDesc(recordId).stream().map(this::procedure).toList();}
 @Transactional public TreatmentPlanResponse createPlan(Long recordId,TreatmentPlanRequest request,UserPrincipal user){var record=records.findById(recordId).orElseThrow(()->new ClinicalRecordNotFoundException(recordId));if(plans.findByClinicalRecordIdOrderByIdDesc(recordId).stream().anyMatch(p->"ACTIVE".equals(p.getStatus())))throw new TreatmentException("ACTIVE_PLAN_EXISTS","Ya existe un plan de tratamiento activo.");var plan=new TreatmentPlan(record,request.title(),user.id());for(var input:request.items()){DentalPiece piece=input.pieceCode()==null?null:piece(input.pieceCode());plan.add(new TreatmentPlanItem(plan,piece,input.description(),input.priority(),input.sessionsEstimated(),input.observations(),user.id()));}return plan(plans.save(plan));}
 @Transactional(readOnly=true)public List<TreatmentPlanResponse> plans(Long recordId){requireRecord(recordId);return plans.findByClinicalRecordIdOrderByIdDesc(recordId).stream().map(this::plan).toList();}
 @Transactional public TreatmentPlanResponse changeItemStatus(Long recordId,Long planId,Long itemId,TreatmentItemStatus status){var item=items.findByIdAndPlanIdAndPlanClinicalRecordId(itemId,planId,recordId).orElseThrow(()->new TreatmentException("TREATMENT_ITEM_NOT_FOUND","Ítem de plan no encontrado."));item.changeStatus(status);items.save(item);return plans(recordId).stream().filter(p->p.id().equals(planId)).findFirst().orElseThrow();}
 @Transactional public EvolutionClinicalResponse createEvolution(Long recordId,Long consultationId,EvolutionClinicalRequest request,UserPrincipal user){requireRecord(recordId);var consultation=consultations.findByIdAndClinicalRecordId(consultationId,recordId).orElseThrow(()->new ConsultationNotFoundException(consultationId));Long pieceId=request.pieceCode()==null?null:piece(request.pieceCode()).getId();if(request.procedureId()!=null&&!procedures.existsByIdAndConsultationId(request.procedureId(),consultationId))throw new TreatmentException("PROCEDURE_MISMATCH","El procedimiento no pertenece a la consulta.");return evolution(evolutions.save(new DentalEvolution(consultation,request.description(),pieceId,request.procedureId(),request.result(),request.date(),request.nextControl(),user.id())));}
 @Transactional(readOnly=true)public List<EvolutionClinicalResponse> evolutions(Long recordId){requireRecord(recordId);return evolutions.findByConsultationClinicalRecordIdOrderByRecordedAtDescIdDesc(recordId).stream().map(this::evolution).toList();}
 private Set<DentalPiece> resolvePieces(Set<String> codes){Set<DentalPiece> result=new LinkedHashSet<>();codes.forEach(c->result.add(piece(c)));return result;}private DentalPiece piece(String code){return pieces.findByInternalCodeAndActiveTrue(code).orElseThrow(()->new TreatmentException("PIECE_NOT_FOUND","Pieza "+code+" no encontrada."));}private void requireRecord(Long id){if(!records.existsById(id))throw new ClinicalRecordNotFoundException(id);}
 private ProcedureResponse procedure(DentalProcedure p){return new ProcedureResponse(p.getId(),p.getConsultation().getId(),ProcedureType.valueOf(p.getType().getCode()),p.getType().getName(),p.getPieces().stream().map(DentalPiece::getInternalCode).toList(),p.getDiagnosisId(),p.getDescription(),p.getMaterialUsed(),p.getAnesthesiaUsed(),p.getPostInstructions(),p.getStatus(),p.getPerformedAt(),p.getNextControlDate(),p.getCreatedBy());}
 private TreatmentPlanResponse plan(TreatmentPlan p){return new TreatmentPlanResponse(p.getId(),p.getTitle(),p.getStatus(),p.getItems().stream().map(i->new TreatmentPlanResponse.Item(i.getId(),i.getPiece()==null?null:i.getPiece().getInternalCode(),i.getDescription(),i.getPriority(),i.getSessionsEstimated(),i.getStatus(),i.getObservations())).toList());}
 private EvolutionClinicalResponse evolution(DentalEvolution e){String code=e.getDentalPieceId()==null?null:pieces.findById(e.getDentalPieceId()).map(DentalPiece::getInternalCode).orElse(null);return new EvolutionClinicalResponse(e.getId(),e.getConsultation().getId(),code,e.getProcedureId(),e.getDescription(),e.getResult(),e.getRecordedAt(),e.getNextControlDate());}
}
